    [ZAMA_HOST_ERROR__INVALID_CHAIN_TYPE_BYTE]: `host chain id must have type byte 0x01 and the gateway chain id must have type byte 0x00`,
    [ZAMA_HOST_ERROR__INVALID_COPROCESSOR_THRESHOLD]: `coprocessor threshold must be between 1 and the signer count`,
    [ZAMA_HOST_ERROR__INVALID_DELEGATION]: `delegation tuple is invalid`,
    [ZAMA_HOST_ERROR__INVALID_FHE_EXECUTE_ACCOUNT]: `fhe_execute account reference is invalid`,
    [ZAMA_HOST_ERROR__INVALID_FHE_EXECUTE_OPERATION_COUNT]: `fhe_execute operation count is invalid`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_ATTESTATION]: `coprocessor input attestation is invalid`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_HANDLE]: `attestation selected handle does not match`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_HANDLE_CHAIN]: `input handle chain id does not match host config`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_HANDLE_INDEX]: `attestation handle index is invalid`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_HANDLE_TYPE]: `input handle FHE type is unsupported`,
    [ZAMA_HOST_ERROR__INVALID_INPUT_HANDLE_VERSION]: `input handle version is unsupported`,
    [ZAMA_HOST_ERROR__INVALID_KMS_CERTIFICATE]: `KMS public-decrypt certificate is invalid`,
    [ZAMA_HOST_ERROR__INVALID_KMS_CONTEXT]: `KMS context is destroyed or does not match the certificate's committed context`,
    [ZAMA_HOST_ERROR__INVALID_KMS_CONTEXT_ID]: `KMS context id must not be the all-zero id`,
    [ZAMA_HOST_ERROR__INVALID_KMS_THRESHOLD]: `KMS context threshold is invalid`,
    [ZAMA_HOST_ERROR__INVALID_RANDOM_UPPER_BOUND]: `bounded random upper bound is invalid`,
    [ZAMA_HOST_ERROR__INVALID_RETURN_SELECTION]: `invalid execution return selection`,
    [ZAMA_HOST_ERROR__MALFORMED_INPUT_ATTESTATION]: `input attestation payload is malformed`,
    [ZAMA_HOST_ERROR__MUL_DIV_DIVISOR_ZERO]: `fheMulDiv divisor must be non-zero`,
    [ZAMA_HOST_ERROR__NOT_DELEGATED_YET]: `delegation is not granted`,
    [ZAMA_HOST_ERROR__NOT_PAUSER]: `signer is not an enabled pauser`,
    [ZAMA_HOST_ERROR__PAUSER_RECORD_MISMATCH]: `pauser record mismatch`,
    [ZAMA_HOST_ERROR__PDA_CREATION_MISMATCH]: `PDA creation target is invalid`,
    [ZAMA_HOST_ERROR__PERMIT_INVALIDATION_ACCOUNT_INVALID]: `permit invalidation account is not a valid watermark record`,
    [ZAMA_HOST_ERROR__PERMIT_INVALIDATION_PDA_MISMATCH]: `permit invalidation account is not the canonical account for the signer`,
    [ZAMA_HOST_ERROR__PREVIOUS_BANK_HASH_UNAVAILABLE]: `previous bank hash is not available`,
    [ZAMA_HOST_ERROR__PREVIOUS_STORE_MISMATCH]: `encrypted value previous handle does not match the account`,
    [ZAMA_HOST_ERROR__PUBLIC_DECRYPT_PAUSED]: `public-decrypt verification is paused`,
    [ZAMA_HOST_ERROR__PUBLIC_DECRYPT_PROOF_INVALID]: `public-decrypt inclusion proof is invalid`,
    [ZAMA_HOST_ERROR__RAND_NONCE_MISMATCH]: `rand nonce account mismatch`,
    [ZAMA_HOST_ERROR__SCOPE_DENIED]: `application scope is deny-listed`,
    [ZAMA_HOST_ERROR__TOO_MANY_COPROCESSOR_SIGNERS]: `coprocessor signer set exceeds the maximum size`,
    [ZAMA_HOST_ERROR__TOO_MANY_KMS_SIGNERS]: `KMS context exceeds the maximum signer count`,
    [ZAMA_HOST_ERROR__TRANSIENT_ACCOUNT_INVALID]: `invalid transient workspace account`,
